};
use crucible_shmem::{MappedSetupRegion, NodeSlot, WhiteboxMarkerEntry};

const CONTINUATION_TIMEOUT: Duration = Duration::from_secs(120);

fn timer_json(snapshot: &NodeSlotSnapshot) -> Value {
    snapshot.virtual_timer_witness.map_or(Value::Null, |witness| json!({
        "generation": witness.generation,
        "deadline_ps": witness.deadline_ps,
        "deadline_tick": witness.deadline_tick,
        "armed_raw_icount": witness.armed_raw_icount,
        "fired_expire_ps": witness.fired_expire_ps,
        "fired_virtual_ps": witness.fired_virtual_ps,
        "fired_raw_icount": witness.fired_raw_icount,
        "completed": witness.completed,
        "reserved": witness.reserved,
    }))
}

fn state_json(snapshot: &NodeSlotSnapshot) -> Value {
    // Publication counters and futex wake counts are retained as diagnostics
    // separately; the state comparison includes all public semantic fields.
    json!({
        "current_icount": snapshot.current_icount,
        "current_ns": snapshot.current_ns,
        "raw_icount": snapshot.logical_time_raw_icount,
        "max_advance_icount": snapshot.max_advance_icount,
        "idle_wake_icount": snapshot.idle_wake_icount,
        "status": snapshot.status,
        "kind": snapshot.kind,
        "device_io_active": snapshot.device_io_active,
        "advance_stop_condition": snapshot.advance_stop_condition,
        "control_boundary_ack": snapshot.control_boundary_ack,
        "control_boundary_fault_command_frontier": snapshot.control_boundary_fault_command_frontier,
        "control_boundary_capture_request": snapshot.control_boundary_capture_request,
        "restore_target": snapshot.logical_time_restore_target,
        "restore_request": snapshot.logical_time_restore_request,
        "restore_ack": snapshot.logical_time_restore_ack,
        "timer_witness": timer_json(snapshot),
    })
}

fn virtual_bytes(response: &Value, address: u64, count: usize) -> Result<Vec<u8>> {
    let text = response.as_str().ok_or("guest byte read was not text")?;
    let mut bytes = Vec::new();
    for line in text.lines() {
        let Some((observed_address, values)) = line.split_once(':') else {
            continue;
        };
        let expected_address = address.checked_add(bytes.len() as u64)
            .ok_or("guest byte address overflow")?;
        if u64::from_str_radix(observed_address.trim(), 16)? != expected_address {
            return Err("guest byte read is not the contiguous requested range".into());
        }
        for value in values.split_whitespace() {
            let hex = value.strip_prefix("0x").ok_or("invalid guest byte read")?;
