    }
    Ok(bytes)
}

/// Validates first idleness without treating the last control-boundary raw
/// count as a continuously refreshed retirement counter.
fn reply_idle_is_ready(
    snapshot: &NodeSlotSnapshot,
    readiness: &NodeSlotSnapshot,
    consumed: bool,
    completed: usize,
    ceiling: u64,
) -> bool {
    consumed && completed == 1
        && snapshot.status == STATUS_IDLE
        && snapshot.device_io_active == 0
        && snapshot.current_icount > readiness.current_icount
        && snapshot.current_icount < ceiling
        && snapshot.idle_wake_icount > snapshot.current_icount
}

fn validate_paired_pause(
    paused: &NodeSlotSnapshot,
    idle: &NodeSlotSnapshot,
    readiness: &NodeSlotSnapshot,
    request: u32,
) -> Result<()> {
    if paused.control_boundary_ack != request.wrapping_add(1)
        || request & 1 != 0
        || paused.logical_time_raw_icount <= readiness.logical_time_raw_icount
        || paused.idle_wake_icount != paused.current_icount
    {
        return Err("paired pause lacks its fresh raw count, acknowledgement, or quiesced deadline".into());
    }
    let logical_progress = paused.current_icount.checked_sub(readiness.current_icount)
        .ok_or("paired pause logical count regressed")?;
    let raw_progress = paused.logical_time_raw_icount.checked_sub(readiness.logical_time_raw_icount)
        .ok_or("paired pause raw count regressed")?;
    if raw_progress.checked_mul(TICKS_PER_INSTRUCTION) != Some(logical_progress) {
        return Err("NextAuthenticatedIdle continuation changed virtual time without matching retirement".into());
    }

    // These three fields change by the documented owning pause transaction.
    // Every other public semantic field must retain the first idle state.
    let mut expected = state_json(idle);
    expected["raw_icount"] = json!(paused.logical_time_raw_icount);
    expected["idle_wake_icount"] = json!(paused.current_icount);
    expected["control_boundary_ack"] = json!(request.wrapping_add(1));
    if state_json(paused) != expected {
        return Err("paired pause changed the retained first-idle logical/timer/state".into());
    }
    Ok(())
}

fn await_native_pause(
    qmp: &mut Qmp,
    slot: &NodeSlot,
    idle: &NodeSlotSnapshot,
    readiness: &NodeSlotSnapshot,
    request: u32,
) -> Result<(Value, NodeSlotSnapshot)> {
    let deadline = Instant::now() + Duration::from_secs(30);
    loop {
        let snapshot = slot.snapshot();
        if snapshot.current_icount != idle.current_icount
            || snapshot.current_ns != idle.current_ns
            || snapshot.virtual_timer_witness != idle.virtual_timer_witness
        {
            return Err("paired pause moved the retained first idle coordinate or timer".into());
        }
        let status = qmp.command("query-status", json!({}))?;
        if snapshot.control_boundary_ack == request.wrapping_add(1)
            && status["status"] == "paused" && status["running"] == false
        {
            validate_paired_pause(&snapshot, idle, readiness, request)?;
            return Ok((status, snapshot));
        }
        if Instant::now() >= deadline {
            return Err(format!("paired pause timeout: {snapshot:?}; status={status}").into());
        }
        thread::sleep(Duration::from_micros(100));
    }
}

fn timeout_diagnostics(
    qmp: &mut Qmp,
    region: &mut MappedSetupRegion,
    slot: &NodeSlot,
    address: u64,
    completed: &[Value],
    directory: &Path,
) -> Result<()> {
    let before = slot.snapshot();
    let (read_index, write_index) = {
        let ring = region.selectable_reply_ring_mut(0)?;
        (ring.header.read_index(), ring.header.write_index())
    };
    // Diagnostics run only after the qualification has already timed out.
    // No stop, cont, wake, or replacement scheduler grant is sent here.
    let status = qmp.command("query-status", json!({}));
    let response = qmp.command("human-monitor-command", json!({
        "command-line": format!("x/128bx 0x{address:x}"),
    }));
    let bytes = response.as_ref().ok().and_then(|value| virtual_bytes(value, address, 128).ok());
    let after = slot.snapshot();
    fs::write(directory.join("reply-timeout-diagnostics.json"), serde_json::to_vec_pretty(&json!({
        "scope": "post-timeout diagnostics only; no native qualification claim",
        "slot_before": state_json(&before), "slot_after": state_json(&after),
        "public_semantic_state_unchanged": state_json(&before) == state_json(&after),
        "reply_ring_read_index": read_index, "reply_ring_write_index": write_index,
        "completed_markers": completed,
        "status": status.as_ref().ok(), "status_error": status.err().map(|error| error.to_string()),
        "guest_reply_response": response.as_ref().ok(),
        "guest_reply_bytes_hex": bytes.map(|value| value.iter().map(|byte| format!("{byte:02x}")).collect::<String>()),
        "guest_reply_error": response.err().map(|error| error.to_string()),
    }))?)?;
    Ok(())
}

pub(super) fn run(
    qmp: &mut Qmp,
    region: &mut MappedSetupRegion,
    slot: &NodeSlot,
    pending: &(SelectablePendingTransportRecord, u64),
    readiness: &NodeSlotSnapshot,
    process: &mut Process,
    wake: &File,
    directory: &Path,
    ram_bytes: u64,
) -> Result<Value> {
    let (request, request_tick) = pending;
    if request.request().sequence() != 2
        || request.request().reply_capacity() != 128
        || request.raw_icount().checked_add(SELECTABLE_NATIVE_HANDOFF_INSTRUCTIONS)
            != Some(readiness.logical_time_raw_icount)
        || request_tick.checked_add(SELECTABLE_NATIVE_HANDOFF_TICKS_PS)
            != Some(readiness.current_icount)
    {
        return Err("reply continuation requires the exact retained seq2 readiness request".into());
    }
    let reply = SelectionReply::rejected(2, SelectionReplyStatus::Unavailable, [0; 32], [0; 32])?;
    let encoded_reply = reply.encode()?;
    let mut expected_guest_bytes = encoded_reply.clone();
    expected_guest_bytes.resize(128, 0);

    let entry = WhiteboxMarkerEntry::new(
        readiness.current_icount, 0, WHITEBOX_SHMEM_KIND_SELECTABLE_REPLY, &encoded_reply,
    )?;
    {
        let ring = region.selectable_reply_ring_mut(0)?;
        if ring.header.read_index() != 0 || ring.header.write_index() != 0 {
            return Err("reply continuation did not begin with an unused reply ring".into());
        }
        ring.header.enqueue_whitebox_marker(ring.entries, entry)?;
        if ring.header.read_index() != 0 || ring.header.write_index() != 1 {
            return Err("reply publication did not retain its single ring slot".into());
        }
    }
    let ceiling = readiness.current_icount.checked_add(20_000_000_000_000)
        .ok_or("reply liveness ceiling overflow")?;
    slot.publish_scheduler_advance(
        authorize_advance_ceiling(readiness.current_icount, ceiling, None)?,
        AdvanceStopCondition::NextAuthenticatedIdle,
    )?;
    qmp.command("cont", json!({}))?;

    let deadline = Instant::now() + CONTINUATION_TIMEOUT;
    let mut completed = Vec::new();
    let first_idle = loop {
        {
            let ring = region.whitebox_marker_ring_mut(0)?;
            while let Some(record) = ring.header.dequeue_whitebox_marker(ring.entries)? {
                let marker = record.validate()?;
                if marker.kind() != WHITEBOX_SHMEM_KIND_SELECTABLE_COMPLETED
                    || marker.vcpu_index() != 0
                    || marker.current_icount() < readiness.current_icount
                    || marker.payload() != encoded_reply
                {
                    return Err("reply continuation carried an unexpected completion marker".into());
                }
                completed.push(json!({
                    "kind": marker.kind(), "logical_tick": marker.current_icount(),
                    "vcpu": marker.vcpu_index(),
                    "payload_hex": marker.payload().iter().map(|byte| format!("{byte:02x}")).collect::<String>(),
                }));
                if completed.len() > 1 {
                    return Err("reply continuation consumed its reply more than once".into());
                }
            }
        }
        let snapshot = slot.snapshot();
        let consumed = {
            let ring = region.selectable_reply_ring_mut(0)?;
            if ring.header.write_index() != 1 || ring.header.read_index() > 1 {
                return Err("reply continuation changed its single-publication ring indices".into());
            }
            ring.header.read_index() == 1
        };
        if reply_idle_is_ready(&snapshot, readiness, consumed, completed.len(), ceiling) {
            break snapshot;
        }
        if process.0.try_wait()?.is_some() {
            return Err("QEMU exited during native reply continuation".into());
        }
        if Instant::now() >= deadline {
            let diagnostics = timeout_diagnostics(qmp, region, slot, request.guest_virtual_address(), &completed, directory);
            return Err(format!("native reply continuation timeout: {snapshot:?}; diagnostics={diagnostics:?}").into());
        }
        thread::sleep(Duration::from_micros(100));
    };
    // Request admission before raising Pause so an awakened idle callback
    // defers to the paired, post-device main-loop owner. Ring the eventfd only
    // after both public publications, matching the host control protocol.
    let control_request = slot.request_control_boundary(0, None)?;
    region.header().request_pause([slot])?;
    let mut wake_writer = wake;
    wake_writer.write_all(&1_u64.to_ne_bytes())?;
    let (status, stopped) = match await_native_pause(qmp, slot, &first_idle, readiness, control_request) {
        Ok(value) => value,
        Err(error) => {
            let diagnostics = timeout_diagnostics(qmp, region, slot, request.guest_virtual_address(), &completed, directory);
            return Err(format!("{error}; diagnostics={diagnostics:?}").into());
        }
    };
    let registers = qmp.command("human-monitor-command", json!({"command-line":"info registers"}))?;
    let memory_response = qmp.command("human-monitor-command", json!({
        "command-line": format!("x/128bx 0x{:x}", request.guest_virtual_address()),
    }))?;
    let guest_bytes = virtual_bytes(&memory_response, request.guest_virtual_address(), 128)?;
    if guest_bytes != expected_guest_bytes {
        return Err("native reply continuation did not write the complete padded guest reply".into());
    }
    let ram_path = directory.join("ram.reply-idle.bin");
    qmp.command("pmemsave", json!({"val":0,"size":ram_bytes,"filename":ram_path}))?;
    let ram = fs::read(ram_path)?;
    let capture_status = qmp.command("query-status", json!({}))?;
    if ram.len() as u64 != ram_bytes
        || state_json(&slot.snapshot()) != state_json(&stopped)
        || capture_status != status
    {
        return Err("native reply continuation moved during stopped capture".into());
    }
    {
        let ring = region.selectable_reply_ring_mut(0)?;
        if ring.header.read_index() != 1 || ring.header.write_index() != 1 {
            return Err("reply continuation changed its ring after capture".into());
        }
        let markers = region.whitebox_marker_ring_mut(0)?;
        if markers.header.dequeue_whitebox_marker(markers.entries)?.is_some() {
            return Err("reply continuation produced an extra completion after capture".into());
        }
    }
    Ok(json!({
        "scope": "actual native resume and complete reply, first all-vCPU idle, then public paired native pause; no timing claim",
        "reply_ring_read_index": 1, "reply_ring_write_index": 1,
        "reply_address": request.guest_virtual_address(),
        "reply_guest_bytes_hex": guest_bytes.iter().map(|byte| format!("{byte:02x}")).collect::<String>(),
        "completed_markers": completed,
        "first_idle_slot": state_json(&first_idle),
        "paired_control_request": control_request,
        "slot": state_json(&stopped), "registers": registers, "status": status,
        "ram_bytes": ram_bytes, "ram_sha256": format!("{:x}", Sha256::digest(&ram)),
        "publication_diagnostics": {
            "advance_publication_sequence": stopped.advance_publication_sequence,
            "publish_gen": stopped.publish_gen, "wake_signal": stopped.wake_signal,
        },
    }))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn guest_byte_parser_rejects_partial_and_nonbyte_reads() {
        assert!(virtual_bytes(&json!("00000010: 0x01 0x02\n"), 0x10, 3).is_err());
        assert!(virtual_bytes(&json!("00000010: 0x100\n"), 0x10, 1).is_err());
        assert!(virtual_bytes(&json!({"error":"unmapped"}), 0x10, 1).is_err());
        assert!(virtual_bytes(&json!("00000010: 0x01\n00000010: 0x00\n"), 0x10, 2).is_err());
    }

    #[test]
    fn guest_byte_parser_retains_all_zero_padding() -> Result<()> {
        assert_eq!(virtual_bytes(&json!("00000010: 0x01 0x00\n00000012: 0x00 0xff\n"), 0x10, 4)?, [1, 0, 0, 255]);
        Ok(())
    }
    fn stale_raw_idle() -> Result<(NodeSlot, NodeSlotSnapshot, NodeSlotSnapshot)> {
        let slot = NodeSlot::new(crucible_shmem::KIND_VM);
        slot.publish_scheduler_advance(authorize_advance_ceiling(0, 10_000, None)?, AdvanceStopCondition::NextAuthenticatedIdle)?;
        slot.publish_pause_quiesced(1_000, 20)?;
        let readiness = slot.snapshot();
        slot.publish_idle(1_500, 2_000)?;
        let idle = slot.snapshot();
        Ok((slot, readiness, idle))
    }

    #[test]
    fn first_idle_accepts_stale_raw_but_requires_consumption_and_future_deadline() -> Result<()> {
        let (_, readiness, idle) = stale_raw_idle()?;
        assert_eq!(idle.logical_time_raw_icount, readiness.logical_time_raw_icount);
        // Requiring the v2 raw predicate rejects a valid publish_idle state:
        // publish_idle intentionally does not refresh control-boundary raw.
        assert!(!(idle.logical_time_raw_icount > readiness.logical_time_raw_icount));
        assert!(reply_idle_is_ready(&idle, &readiness, true, 1, 10_000));
        assert!(!reply_idle_is_ready(&idle, &readiness, false, 1, 10_000));
        assert!(!reply_idle_is_ready(&idle, &readiness, true, 0, 10_000));
        let mut no_future = idle;
        no_future.idle_wake_icount = no_future.current_icount;
        assert!(!reply_idle_is_ready(&no_future, &readiness, true, 1, 10_000));
        Ok(())
    }

    #[test]
    fn paired_pause_requires_fresh_raw_only_after_owning_ack() -> Result<()> {
        let (slot, readiness, idle) = stale_raw_idle()?;
        let request = slot.request_control_boundary(0, None)?;
        assert!(validate_paired_pause(&slot.snapshot(), &idle, &readiness, request).is_err());
        slot.publish_pause_quiesced(1_500, 30)?;
        assert!(validate_paired_pause(&slot.snapshot(), &idle, &readiness, request).is_err());
        assert_eq!(slot.acknowledge_control_boundary(), request.wrapping_add(1));
        let paused = slot.snapshot();
        validate_paired_pause(&paused, &idle, &readiness, request)?;
        let mut stale = paused;
        stale.logical_time_raw_icount = readiness.logical_time_raw_icount;
        assert!(validate_paired_pause(&stale, &idle, &readiness, request).is_err());
        let mut drift = paused;
        drift.current_ns += 1;
        assert!(validate_paired_pause(&drift, &idle, &readiness, request).is_err());
        Ok(())
    }

}

